#!/usr/bin/env bash
# Install only the read-only process scanner, not the agent or game binaries.
set -euo pipefail
[[ "$(id -u)" -eq 0 ]] || { echo 'Run as root'; exit 1; }
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
install -o root -g root -m 755 "$SCRIPT_DIR/playbound-update-scan" /usr/local/sbin/playbound-update-scan
SCANNER_RULE="$(mktemp)"
trap 'rm -f -- "$SCANNER_RULE"' EXIT
printf '%s\n' 'playbound ALL=(root) NOPASSWD: /usr/local/sbin/playbound-update-scan counter-strike-2, /usr/local/sbin/playbound-update-scan team-fortress-2, /usr/local/sbin/playbound-update-scan unturned, /usr/local/sbin/playbound-update-scan counter-strike-source, /usr/local/sbin/playbound-update-scan core-keeper, /usr/local/sbin/playbound-update-scan dont-starve-together, /usr/local/sbin/playbound-update-scan barotrauma, /usr/local/sbin/playbound-update-scan necesse, /usr/local/sbin/playbound-update-scan aneurism-iv, /usr/local/sbin/playbound-update-scan wolfenstein-enemy-territory, /usr/local/sbin/playbound-update-scan openmohaa, /usr/local/sbin/playbound-update-scan unvanquished, /usr/local/sbin/playbound-update-scan mindustry, /usr/local/sbin/playbound-update-scan openra, /usr/local/sbin/playbound-update-scan openhv, /usr/local/sbin/playbound-update-scan earth-2140-trilogy, /usr/local/sbin/playbound-update-scan hypersomnia, /usr/local/sbin/playbound-update-scan assaultcube, /usr/local/sbin/playbound-update-scan factorio, /usr/local/sbin/playbound-update-scan terraria, /usr/local/sbin/playbound-update-scan bzflag, /usr/local/sbin/playbound-update-scan hedgewars, /usr/local/sbin/playbound-update-scan openttd, /usr/local/sbin/playbound-update-scan luanti, /usr/local/sbin/playbound-update-scan battle-for-wesnoth, /usr/local/sbin/playbound-update-scan rimworld-together, /usr/local/sbin/playbound-update-scan flightgear, /usr/local/sbin/playbound-update-scan teeworlds, /usr/local/sbin/playbound-update-scan supertuxkart, /usr/local/sbin/playbound-update-scan openarena, /usr/local/sbin/playbound-update-scan 0ad, /usr/local/sbin/playbound-update-scan xonotic' > "$SCANNER_RULE"
visudo -cf "$SCANNER_RULE"
install -o root -g root -m 440 "$SCANNER_RULE" /etc/sudoers.d/playbound-update-scan
